const fs=require('fs');
const puppeteer=require('puppeteer-core');
const PRODUCT='ac633ec0e431668b000c105cb05bc81da93ebd2d';
const viewports=[{name:'1920x1080',width:1920,height:1080},{name:'1440x900',width:1440,height:900},{name:'768x1024',width:768,height:1024},{name:'390x844',width:390,height:844},{name:'360x800',width:360,height:800}];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const browser=await puppeteer.launch({headless:true,executablePath:process.env.CHROME,args:['--no-sandbox','--disable-dev-shm-usage']});const out={productSha:PRODUCT,cases:{},failures:[]};fs.mkdirSync('gate-a-postfix/lazy',{recursive:true});for(const vp of viewports){const p=await browser.newPage(),fail=[];p.on('requestfailed',r=>fail.push({url:r.url(),error:r.failure()?.errorText||''}));await p.setViewport({width:vp.width,height:vp.height,deviceScaleFactor:1});await p.goto('http://127.0.0.1:8000/energy.html',{waitUntil:'domcontentloaded',timeout:30000});const found=await p.evaluate(()=>Boolean(document.querySelector('img[src="assets/phase08/operations-context.webp"]')));if(found){await p.evaluate(()=>document.querySelector('img[src="assets/phase08/operations-context.webp"]').scrollIntoView({block:'center'}));await p.waitForFunction(()=>{const i=document.querySelector('img[src="assets/phase08/operations-context.webp"]');return i&&i.complete&&i.naturalWidth>0&&i.naturalHeight>0},{timeout:10000});await sleep(180)}const data=await p.evaluate(()=>{const i=document.querySelector('img[src="assets/phase08/operations-context.webp"]');if(!i)return null;const r=i.getBoundingClientRect();return{complete:i.complete,naturalWidth:i.naturalWidth,naturalHeight:i.naturalHeight,rect:{left:r.left,top:r.top,right:r.right,bottom:r.bottom,width:r.width,height:r.height},src:i.getAttribute('src')}});out.cases[vp.name]={found,data,requestFailures:fail};if(!found||!data?.complete||data.naturalWidth!==640||data.naturalHeight!==800||fail.some(x=>x.url.includes('operations-context.webp')))out.failures.push({viewport:vp.name,found,data,requestFailures:fail});await p.screenshot({path:`gate-a-postfix/lazy/energy-operations-${vp.name}.png`});await p.close()}fs.writeFileSync('gate-a-postfix/lazy/lazy-report.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out,null,2));await browser.close();if(out.failures.length)process.exit(2)})().catch(e=>{console.error(e);process.exit(1)});
